export function saveUser(userId: string, name: string): void {
  const users: { id: string; name: string }[] = [];
  const newUser: { id: string; name: string } = { id: userId, name };
  users.push(newUser);
  console.log('User saved:', newUser);
}

export function loadUser(userId: string): { id: string; name: string } | undefined {
  const users: { id: string; name: string }[] = [];
  const foundUser = users.find(u => u.id === userId);
  if (foundUser) {
    console.log('User loaded:', foundUser);
    return foundUser;
  }
  return undefined;
}

